    "POST /account/connections/web3/complete": {auth:"ceremony",fields:[field("message","textarea",true,"پیام دقیق start","Exact start message","EXACT_MESSAGE_FROM_START"),field("signature","textarea",true,"امضا","Signature","0xSIGNATURE")]},
    "PATCH /account/profile": {auth:"session",helpFa:"فقط فیلدهای ارسال‌شده‌ی پروفایل را تغییر می‌دهد؛ ایمیل و موبایل ceremony جداگانه دارند.",helpEn:"Updates only supplied profile fields; email and phone use separate verified ceremonies.",fields:[field("display_name","text",false,"نام نمایشی","Display name","Example Rider"),field("preferred_username","text",false,"نام کاربری ترجیحی","Preferred username","example-rider"),field("locale","text",false,"زبان/منطقه","Locale","fa-IR"),field("picture","url",false,"آدرس تصویر","Picture URL","https://cdn.example.com/avatar.png")]},
    "PUT /account/profile": {auth:"session",helpFa:"برای سازگاری همان semantics جزئی PATCH را اجرا می‌کند.",helpEn:"Compatibility route with the same partial-update semantics as PATCH.",fields:[field("display_name","text",false,"نام نمایشی","Display name","Example Rider"),field("preferred_username","text",false,"نام کاربری ترجیحی","Preferred username","example-rider"),field("locale","text",false,"زبان/منطقه","Locale","fa-IR"),field("picture","url",false,"آدرس تصویر","Picture URL","https://cdn.example.com/avatar.png")]},
