    "POST /auth/web3/complete": {auth:"ceremony",fields:[field("message","textarea",true,"پیام دقیق start","Exact start message","EXACT_MESSAGE_FROM_START"),field("signature","textarea",true,"امضای کیف پول","Wallet signature","0xSIGNATURE")]},
