    "POST /oauth/revoke": {auth:"oauth",contentType:"application/x-www-form-urlencoded",fields:[field("client_id","text",true,"شناسه Client","Client ID","CLIENT_ID"),field("client_secret","password",true,"رمز Client","Client secret","CLIENT_SECRET"),field("token","text",true,"Token","Token","REFRESH_OR_ACCESS_TOKEN")]},
    "POST /admin/applications": {auth:"admin",fields:[field("identifier","text",true,"شناسه محصول","Product identifier","ride-app"),field("name","text",true,"نام محصول","Product name","Ride App"),field("environment","text",true,"محیط","Environment","development")]},
    "POST /admin/clients": {auth:"admin",fields:[field("application_id","text",true,"شناسه Application","Application ID","APPLICATION_ID"),field("name","text",true,"نام Client","Client name","Ride Web"),field("kind","text",true,"نوع Client","Client kind","browser"),field("redirect_uris","array",true,"Redirect URIها","Redirect URIs","https://app.example.com/callback"),field("scopes","array",true,"Scopeها","Scopes","openid, profile, offline_access")]},
    "POST /admin/resources": {auth:"admin",fields:[field("audience","url",true,"Audience","Audience","https://api.example.com/rides"),field("name","text",true,"نام API","API name","Ride API"),field("scopes","array",true,"Scopeها","Scopes","rides:read, rides:write")]},
    "POST /evidence/challenge": {auth:"bearer",fields:[field("provider","text",true,"شناسه Provider","Provider ID","PROVIDER_ID")]},
