  function responsePanel(){const result=state.explorer.response,loading=state.busy==="request",headers=result?Object.entries(result.headers||{}):[];return `<section class="response-panel ${!result?"is-empty":""}"><div class="response-head">${editorChrome("response.json")}<span class="response-title">${t("پاسخ واقعی OpenProof","Live OpenProof response")}</span><span class="response-meta">${loading?`<i class="loading"></i> ${t("در حال انتظار","Waiting")}`:result?`<b class="${result.status<400?"http-ok":"http-bad"}">HTTP ${result.status}</b> · ${result.duration_ms} ms`:t("هنوز اجرا نشده","Not run yet")}</span></div>${loading?`<div class="response-loading"><i class="loading"></i><b>${t("درخواست به OpenProof ارسال شد…","Request sent to OpenProof…")}</b><span>${t("پاسخ واقعی در همین بخش نمایش داده می‌شود.","The live response will appear here.")}</span></div>`:result?`${headers.length?`<div class="response-headers">${headers.map(([name,value])=>`<span><b>${escapeHtml(name)}</b>: ${escapeHtml(value)}</span>`).join("")}</div>`:""}${codeBlock(pretty(result.body),"json")}`:`<div class="response-empty">${icon("terminal")}<div><b>${t("پاسخی برای نمایش نیست","No response yet")}</b><span>${t("ورودی و منبع credential را بررسی کنید، سپس «ارسال درخواست» را بزنید.","Review the inputs and credential source, then select Send request.")}</span></div></div>`}</section>`;}
