  function inboxPage(){return `<section class="page"><div class="surface inbox-toolbar"><p>${t("این صندوق پیاده‌سازی development برای delivery webhook است؛ production باید proof را با ایمیل/SMS ارسال کند.","This inbox is the development delivery-webhook adapter; production should send proof through email/SMS.")}</p><button class="button button-secondary" data-action="refresh-messages">${icon("refresh")}${t("به‌روزرسانی","Refresh")}</button></div>${state.messages.length?`<div class="message-grid">${state.messages.map(messageCard).join("")}</div>`:`<div class="surface empty-state">${icon("inbox")}<h3>${t("پیامی تحویل نشده","No deliveries yet")}</h3><p>${t("از آزمایشگاه هویت یک حساب جدید بسازید.","Create an account from the Identity Workbench.")}</p></div>`}</section>`;}

